import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate, Trend } from 'k6/metrics';
import * as shard from './lib/shard.js';

// Load environment configuration generated by setup.ts
const env = JSON.parse(open('./k6-env.json'));

const cacheHits = new Rate('cache_hits');
const readDuration = new Trend('read_duration_ms');

// #251 distributed run: nginx's per-IP limiter caps admission by REQUEST RATE, not VU count,
// so a shard plans its load in r/s, not VUs — dividing 1000 VUs by N still produces a VU count
// whose think-time-adjusted request rate is many times the per-IP budget (documented in
// README.md "Per-shard math"). Each shard instead runs its own safe, fixed rate; N machines
// running it at once is what reproduces the read-heavy load, at whatever aggregate rate 3
// honest source IPs can cleanly sustain through the real nginx edge. With no SHARD set this
// scenario is byte-for-byte what it was before #251 (VU-driven, single machine).
const shardInfo = shard.shardFromEnv(__ENV);
const ratePerSecond = Number(__ENV.RATE_PER_SHARD || shard.SAFE_RATE_PER_SHARD);
if (shardInfo) shard.assertRateSafe(ratePerSecond, 'k6:read (01-read-products)');

export const options = {
  scenarios: {
    read_heavy: shardInfo
      ? {
          executor: 'ramping-arrival-rate',
          startRate: 0,
          timeUnit: '1s',
          preAllocatedVUs: 60,
          maxVUs: 150,
          stages: [
            { duration: '5s', target: Math.round(ratePerSecond * 0.33) },
            { duration: '10s', target: ratePerSecond },
            { duration: '15s', target: ratePerSecond },
            { duration: '5s', target: 0 },
          ],
        }
      : {
          executor: 'ramping-vus',
          startVUs: 0,
          stages: [
            { duration: '5s', target: 200 },
            { duration: '10s', target: 1000 },
            { duration: '15s', target: 1000 },
            { duration: '5s', target: 0 },
          ],
          gracefulRampDown: '2s',
        },
  },
  thresholds: {
    // Rubric requirement: p95 < 200ms, cache hit > 90%, error < 0.1%
    http_req_duration: ['p(95)<200'],
    cache_hits: ['rate>0.90'],
    http_req_failed: ['rate<0.001'],
  },
};

export default function () {
  const url = `${env.baseUrl}/api/v1/products?page=1&limit=20`;
  const params = {
    headers: {
      Authorization: `Bearer ${env.boToken}`,
      Accept: 'application/json',
    },
    tags: { name: 'GetProducts' },
  };

  const res = http.get(url, params);
  readDuration.add(res.timings.duration);

  const isCacheHit = res.headers['X-Cache'] === 'HIT';
  cacheHits.add(isCacheHit);

  check(res, {
    'status is 200': (r) => r.status === 200,
    'has data array': (r) => {
      try {
        const body = JSON.parse(r.body);
        return body.status === 'success' && Array.isArray(body.data);
      } catch {
        return false;
      }
    },
  });

  sleep(0.2);
}
